def estimate_funnel_latency_ms(n_candidates=1000, batch_size=100, ms_per_batch=1.2):
    batches = math.ceil(n_candidates / batch_size)
    return round(batches * ms_per_batch, 2)  # ~12ms for 1000 items

def two_tower_score(user_vec, item_vec):
    # L2-normalized vectors: dot product equals cosine similarity
    if len(user_vec) != len(item_vec):
        raise ValueError('Embedding dimension mismatch')
    return sum(u * v for u, v in zip(user_vec, item_vec))

def combined_utility(p_click, p_dwell, p_hide):
    # Penalize clickbait (high click, low dwell, high hide)
    return round((1.0 * p_click) + (2.5 * p_dwell) - (5.0 * p_hide), 4)

def mmr_select(candidates, selected, lam=0.7):
    best, best_score = None, -1e9
    for c in candidates:
        sim = max((cosine(c['vec'], s['vec']) for s in selected), default=0.0)
        score = lam * c['utility'] - (1 - lam) * sim
        if score > best_score:
            best, best_score = c, score
    return best

def apply_logq_correction(logits, item_probs):
    # Subtract log sampling probability from negative logits
    return [l - math.log(max(p, 1e-9)) for l, p in zip(logits, item_probs)]
